  &lt;span class="nl"&gt;timeZone&lt;/span&gt;&lt;span class="p"&gt;?:&lt;/span&gt; &lt;span class="kr"&gt;string&lt;/span&gt;&lt;span class="p"&gt;;&lt;/span&gt; &lt;span class="c1"&gt;// Ej: 'UTC', 'Europe/London'&lt;/span&gt;
